script:
export const meta = {
  name: 'v5-human-verifier-rewrite',
  description: 'Rewrite all 4,647 human verifier sentences (gatsby-v5) into explicit, artifact-named, layman-clear one-liners; meaning and strictness unchanged',
  phases: [{ title: 'Rewrite', detail: '20 agents x 5 tasks over the human checks' }],
}

const DIR = '/private/tmp/claude-501/-Users-dhiren-Downloads-Deccan/aa9e6dfc-7579-493e-a3a8-45be309ed406/scratchpad/v5rw/human'
const pad = n => String(n).padStart(2, '0')
const IDS = []
for (let i = 1; i <= 30; i++) IDS.push('PHOTO-' + pad(i))
for (let i = 1; i <= 15; i++) IDS.push('VECTOR-' + pad(i))
for (let i = 1; i <= 35; i++) IDS.push('LAYOUT-' + pad(i))
for (let i = 1; i <= 20; i++) IDS.push('MOTION-' + pad(i))
const BATCHES = []
for (let i = 0; i < IDS.length; i += 5) BATCHES.push(IDS.slice(i, i + 5))

const SCHEMA = {
  type: 'object',
  properties: {
    rewrites: {
      type: 'array',
      items: {
        type: 'object',
        properties: { check_id: { type: 'string' }, text: { type: 'string' } },
        required: ['check_id', 'text'],
      },
    },
  },
  required: ['rewrites'],
}

function prompt(ids) {
  return `You are rewriting HUMAN verifier statements for a creative-AI benchmark review page. Reviewers (creative experts, but write for a layman) answer each one Yes/No in under 20 seconds. Your rewrites must be explicit, name the exact artifact, and be instantly understandable — while keeping the meaning and strictness IDENTICAL.

For each task id in ${JSON.stringify(ids)}, Read the file ${DIR}/<TASK_ID>.json — an array of human check objects with fields: check_id, check (current wording), artifact_name, artifact_file, requirement, expected_value, expected_field, location, evidence_reference, reference_assets.

REWRITE RULES (strict):
1. ONE sentence per check (an em-dash clause is fine). Target ≤28 words, hard cap 35.
2. Name the artifact exactly once, as: \u201c{artifact_name}\u201d ({artifact_file}). Never start with a bare file path. If artifact_name is missing, use the filename alone.
3. If expected_value exists, quote it verbatim in \u201ccurly quotes\u201d inside the sentence. If location/evidence names a source file + row (e.g. cornerandcure_items.csv, row 2), name it: \u2014 as approved in cornerandcure_items.csv, row 2. If expected_value is longer than ~12 words, instead say it matches the approved <field> in <source> word for word (beginning \u201cfirst few words\u2026\u201d).
4. Plain words a layman gets at first glance. Replace jargon: 'visually subordinate' -> 'reads as smaller/secondary'; 'agrees with the approved record' -> 'says exactly what the approved record says'; 'not cut off' -> 'fully visible \u2014 no letters cut off at the edge'; 'legible at delivered size' -> 'easy to read at the size it will actually be shown'.
5. MEANING AND STRICTNESS UNCHANGED. Never add, drop, soften or tighten a requirement. Keep 'exactly' exact. Keep every named size, page, record or brand reference. The check must stay answerable Yes/No by looking at the named file.
6. Present tense, neutral plain English. Use typographic quotes \u201c \u201d for quoted values. No markdown, no bullet text — just the sentence.

EXAMPLES of the target voice:
- OLD: 'deliverables/cold-label-r002.pdf \u2014 Cold-case label - The Corner Reuben - Half (cold-label-r002.pdf): The allergen wording agrees with the approved item record.'
  NEW: 'The allergen line on \u201cCold-case label - The Corner Reuben - Half\u201d (cold-label-r002.pdf) says exactly what the approved record says \u2014 cornerandcure_items.csv, row 2.'
- OLD: '...: At actual print size, the item name text is not cut off.'
  NEW: 'Printed at real size, the item name on \u201cCold-case label - The Corner Reuben - Half\u201d (cold-label-r002.pdf) is fully visible \u2014 no letters cut off at the edge.'
- OLD: '...: The product benefit is visually subordinate to the product name.'
  NEW: 'On \u201cSkincare product-page image - Clarity Vitamin C Serum\u201d (pdp-r002.png), the product name is clearly the bigger text and the benefit line reads as secondary.'
- OLD: '...: Editable design opens in the application named in the source package.'
  NEW: 'The editable design inside \u201cAurelian Skin / product-page editable source\u201d (pdp.zip) opens as a real working file in the design app named in the package.'

Return the structured object: rewrites = one {check_id, text} for EVERY check in EVERY file you read (all ${ids.length} tasks, complete coverage — do not skip any check_id). Count them before returning.`
}

phase('Rewrite')
const results = await parallel(BATCHES.map((ids) => () =>
  agent(prompt(ids), { label: `rewrite:${ids[0]}..${ids[ids.length-1]}`, phase: 'Rewrite', agentType: 'general-purpose', schema: SCHEMA })
))

const all = results.filter(Boolean).flatMap(r => (r && r.rewrites) || [])
return { batches: results.length, null_batches: results.filter(r => !r).length, rewrites: all.length, items: all }
